type NetworkState =
  | { status: "loading" }
  | { status: "success"; data: string[] }
  | { status: "error"; message: string };

function assertNever(x: never): never {
  throw new Error(`Unhandled union variant: ${JSON.stringify(x)}`);
}

function renderUI(state: NetworkState): string {
  switch (state.status) {
    case "loading":
      return "Spinner active...";
    case "success":
      return `Items: ${state.data.join(", ")}`;
    case "error":
      return `Error: ${state.message}`;
    default:
      return assertNever(state);
  }
}

console.log("=== 02: Discriminated Unions ===");
console.log(renderUI({ status: "success", data: ["Go", "Rust", "TS"] }));

