function LogMethod(target: any, context: ClassMethodDecoratorContext) {
  return function (this: any, ...args: any[]) {
    console.log(`[LOG] Calling method: ${String(context.name)} with args:`, args);
    return target.apply(this, args);
  };
}

class Calculator {
