function ExecutionTimer(target: any, context: ClassMethodDecoratorContext) {
  return function (this: any, ...args: any[]) {
    const start = performance.now();
    const result = target.apply(this, args);
    const elapsed = performance.now() - start;
    console.log(`Method ${String(context.name)} took ${elapsed.toFixed(3)}ms`);
    return result;
  };
}

class DataProcessor {
  @ExecutionTimer
  process(): void {
    for (let i = 0; i < 1_000_000; i++) {}
  }
}

